const CACHE="nl-trails-v29";
const APP=["./","./index.html","./styles.css","./app.js","./manifest.webmanifest","./icon.svg","./trailway-data.js","./trails-data.js","./gnta-data.js","./north-data.js","./northern-peninsula-data.js","./northern-resource-roads.js","./mapped-data.js","./community-atv-data.js","./osm-poi-data.js","./flowers-cove-data.js","./expanded-walking-data.js","./provincial-parks-data.js","./driving-data.js","./activity-data.js","./enriched-data.js"];
self.addEventListener("install",event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(APP)).then(()=>self.skipWaiting())));
self.addEventListener("activate",event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener("fetch",event=>{if(event.request.method!=="GET")return;event.respondWith(caches.match(event.request).then(hit=>hit||fetch(event.request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));return response}).catch(()=>caches.match("./index.html"))))});
